type row struct {
	key string
	val int
}

type batch struct {
	seq  int
	rows []row
}

const n_batches = 8

func build_batch(seq int) batch {
	var rows []row
	for i := 0; i < 4; i++ {
		rows = append(rows, row{key: fmt.Sprintf("k%v-%v", seq, i), val: seq*10 + i})
	}
	return batch{seq: seq, rows: rows}
}

func persist(rows []row) int {
	return len(rows)
}

func consumer(batches <-chan batch, acks chan<- int) {
	for b := range batches {
		persist(b.rows)
		acks <- b.seq
	}
}

func main() {
	batches := make(chan batch, 8)
	acks := make(chan int, 8)
	go consumer(batches, acks)
	for seq := 0; seq < n_batches; seq++ {
		b := build_batch(seq)
		batches <- b
	}
	close(batches)
	for hyBlank0 := 0; hyBlank0 < n_batches; hyBlank0++ {
		<-acks
	}
	fmt.Println(fmt.Sprintf("ingested %v batches", n_batches))
}

