)

const n_probes = 4

const calls = 1000

var thresholds = []int{10, 50, 250, 1000}

type sample struct {
	probe int
	above int
}

func measure(i int, c int) int {
	return (i*137 + c*31) % 1200
}

func probe(id int, n int, hits *atomic.Int64, samples chan<- sample) {
	var above int
	for c := 0; c < n; c++ {
		ms := measure(id, c)
		if ms > thresholds[3] {
			hits.Add(1)
			above++
		}
	}
	samples <- sample{probe: id, above: above}
}

func main() {
	var hits atomic.Int64
	samples := make(chan sample, n_probes)
	for i := 0; i < n_probes; i++ {
		go probe(i, calls, &hits, samples)
	}
	var total int
	for hyBlank0 := 0; hyBlank0 < n_probes; hyBlank0++ {
		s := <-samples
		total += s.above
	}
	slow := thresholds[3]
	fmt.Println(fmt.Sprintf("calls over %vms: atomic=%v reported=%v", slow, hits.Load(), total))
}

