)

const n_workers = 4

var seed_urls = []string{"https://example.com/a", "https://example.com/b", "https://example.com/c", "https://example.com/d", "https://example.com/e", "https://example.com/f"}

type pool_stats struct {
	mu        sync.Mutex
	processed int
	failures  int
}

func fetch(url string) bool {
	return len(url)%3 != 0
}

func worker(id int, jobs <-chan string, stats *pool_stats, done chan<- bool) {
	for url := range jobs {
		ok := fetch(url)
		stats.mu.Lock()
		stats.processed++
		if !ok {
			stats.failures++
		}
		stats.mu.Unlock()
	}
	done <- true
}

func main() {
	{ // managed [mutex] pool stats under the pool mutex (lock stays) (audited via hyb check --report-managed) tickets: CORPUS-18
		jobs := make(chan string, len(seed_urls))
		stats := pool_stats{}
		done := make(chan bool, n_workers)
		for i := 0; i < n_workers; i++ {
			go worker(i, jobs, &stats, done)
		}
		for _, url := range seed_urls {
			jobs <- url
		}
		close(jobs)
		for hyBlank0 := 0; hyBlank0 < n_workers; hyBlank0++ {
			<-done
		}
		stats.mu.Lock()
		p, f := stats.processed, stats.failures
		stats.mu.Unlock()
		fmt.Println(fmt.Sprintf("processed=%v failures=%v", p, f))
	}
}

